 q('#pv2StudentSave',m.wrap).onclick=async()=>{const name=q('#pv2StudentName',m.wrap).value.trim(),nns=q('#pv2StudentNns',m.wrap).value.trim(),msg=q('.professor-msg',m.wrap);if(!name){msg.textContent=tr('اكتب اسم التلميذ','Saisissez le nom de l’élève');return}const cls=classById(classId);cls.students=Array.isArray(cls.students)?cls.students:[];if(nns&&cls.students.some(s=>String(s.nns||'')===nns)){msg.textContent=tr('هذا NNS موجود في القسم','Ce NNS existe déjà dans la classe');return}cls.students.push({id:uid(),name,nns});try{await saveProfile(tr('تمت إضافة التلميذ','Élève ajouté'));m.close();onDone?.()}catch{msg.textContent=tr('تعذر الحفظ','Enregistrement impossible')}}
