 const siblingSubjects=assignmentsForClass(a.classId),subjectSwitcher=siblingSubjects.length>1?`<div class="prof-subject-switch"><span>${tr('مواد هذا القسم','Matières de cette classe')}</span><div>${siblingSubjects.map(s=>`<button class="${s.id===a.id?'on':''}" data-switch-subject="${esc(s.id)}">${esc(profSubject(s.subject))}</button>`).join('')}</div></div>`:'';

 const el=root();el.innerHTML=`<div class="professor-shell">${topbar(profSubject(a.subject),profClass(cls?.name||''))}<section class="prof-page-head"><div><button id="pv2BackGrade" class="prof-back-inline">‹ ${tr('رجوع','Retour')}</button><span class="professor-badge">${tr('اختبار واحد + امتحان واحد في كل فصل','Un test + un examen par trimestre')}</span><h1>${esc(profSubject(a.subject))}</h1><p>${esc(profClass(cls?.name||''))} · ${tr('المعامل','Coefficient')} ${coefficient} ${l?'· 🔗 '+l.memberCount+' '+tr('أساتذة','professeurs'):''}</p></div><div><button class="primary" id="pv2SaveGrades">${tr('حفظ الدرجات','Enregistrer les notes')}</button><button id="pv2EditCoefficient">${tr('المعامل','Coefficient')} ×${coefficient}</button>${canManageRoster?`<button id="pv2AddStudentGrade">+ ${tr('تلميذ','Élève')}</button>`:''}</div></section><section class="professor-content">${subjectSwitcher}<div class="prof-term-tabs">${termTabs}</div><div class="prof-term-formula"><b>${tr('طريقة الحساب','Formule')}</b><span>${esc(termFormula(term))}</span><small>${tr('بعد حساب معدل المادة يُضرب في معامل المادة للحصول على النقاط الموزونة.','Après le calcul de la moyenne, elle est multipliée par le coefficient de la matière.')}</small></div><div class="professor-table-wrap"><table class="professor-grade-table"><thead><tr><th>#</th><th>${tr('التلميذ','Élève')}</th><th>${tr('الاختبار '+term+' /20','Test '+term+' /20')}</th><th>${tr('الامتحان '+term+' /20','Examen '+term+' /20')}</th><th>${tr('المجموع /40','Total /40')}</th><th>${tr('معدل المادة /20','Moyenne /20')}</th><th>${tr('بعد المعامل','Pondéré')}</th></tr></thead><tbody>${rows||`<tr><td colspan="7" class="professor-no-students">${canManageRoster?tr('أضف تلاميذ القسم أولًا.','Ajoutez d’abord les élèves de la classe.'):tr('قائمة القسم الموحدة فارغة حاليًا. منشئ الرمز هو من يدير التلاميذ.','La liste unifiée est vide. Le créateur du code gère les élèves.')}</td></tr>`}</tbody></table></div><div class="prof-save-bar"><span id="pv2SaveState">${tr('لا توجد تغييرات غير محفوظة','Aucune modification non enregistrée')}</span><small>${term===1?tr('الفصل الأول يحتاج خ1 وام1.','Le trimestre 1 nécessite Test 1 et Examen 1.'):term===2?tr('الفصل الثاني يحتاج درجات الفصلين الأول والثاني كاملة.','Le trimestre 2 nécessite les notes complètes des trimestres 1 et 2.'):tr('الفصل الثالث يحتاج درجات الفصول الثلاثة كاملة.','Le trimestre 3 nécessite les notes complètes des trois trimestres.')}</small></div></section>${nav('grades')}</div>`;
 bindTop(el);bindNav(el);q('#pv2BackGrade',el).onclick=async()=>{await flushGradeAutosave();openClass(a.classId)};q('#pv2EditCoefficient',el).onclick=async()=>{await flushGradeAutosave();editCoefficient(id)};if(canManageRoster)q('#pv2AddStudentGrade',el).onclick=async()=>{await flushGradeAutosave();addStudent(a.classId,()=>openGrades(id,term))};qa('[data-switch-subject]',el).forEach(b=>b.onclick=async()=>{await flushGradeAutosave();openGrades(b.dataset.switchSubject,term)});qa('[data-prof-term]',el).forEach(b=>b.onclick=async()=>{await flushGradeAutosave();openGrades(id,Number(b.dataset.profTerm))});
 const recalc=sid=>{const m=marks[sid]||{},testValue=markNumber(m[testKey]),examValue=markNumber(m[examKey]),pairTotal=testValue==null||examValue==null?null:testValue+examValue,avg=termResult(m,term),weighted=avg==null?null:avg*coefficient;q(`[data-total="${CSS.escape(sid)}"]`,el).textContent=pairTotal==null?'—':pairTotal.toFixed(2);q(`[data-avg="${CSS.escape(sid)}"]`,el).textContent=avg==null?'—':avg.toFixed(2);q(`[data-weighted="${CSS.escape(sid)}"]`,el).textContent=weighted==null?'—':weighted.toFixed(2)};
