 return `<div class="official-head"><div class="official-side official-admin"><div class="official-strong">${esc(rep)}</div><div>${esc(min)}</div>${region?`<div class="official-line"><span>${tr('الإدارة الجهوية للتربية:','Direction régionale de l’Éducation :')}</span><b>${esc(region)}</b></div>`:''}${inspection?`<div class="official-line"><span>${tr('المفتشية:','Inspection :')}</span><b>${esc(inspection)}</b></div>`:''}</div><div class="official-center"><div class="basmala" lang="ar" dir="rtl">بسم الله الرحمن الرحيم</div><img src="${location.origin}/1280px-National_Seal_of_Mauritania.svg.png" alt="Mauritanie"></div><div class="official-side official-meta"><div class="official-strong">${esc(motto)}</div>${profile.year?`<div class="official-line"><span>${tr('السنة الدراسية:','Année scolaire :')}</span><b dir="ltr">${esc(profile.year)}</b></div>`:''}${school?`<div class="official-line"><span>${tr('المؤسسة:','Établissement :')}</span><b>${esc(school)}</b></div>`:''}${profile.schoolNns?`<div class="official-line"><span>${tr('الرقم المدرسي:','N° scolaire :')}</span><b dir="ltr">${esc(profile.schoolNns)}</b></div>`:''}${className?`<div class="official-line"><span>${tr('القسم:','Classe :')}</span><b>${esc(profClass(className))}</b></div>`:''}<div class="official-line"><span>${tr('الفصل:','Trimestre :')}</span><b>${esc(professorTermLabel(term))}</b></div></div></div>`
